#define main ic_campaign_main
#include "ic.cpp"
#undef main
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];auto family=load(root+"/data/family.json"),fixtures=load(root+"/data/fixtures.json");EC ec{val(family["nodes"][0]["a"]),val(family["nodes"][0]["b"])};Point P=point(fixtures["0"][0]["P"]);std::array<U,12>alpha={13,29,47,71,101,137,179,227,281,347,419,503};std::vector<Point>base;for(U a:alpha)base.push_back(ec.scalar(a,P));RowSpace matrix;json setup=json::array();for(int i=0;i<24&&matrix.rows.size()<12;i++){int left=i<12?i:i-12,right=i<11?i+1:i==11?2:i-12;Point R=ec.op(base[left],base[right]);U t=add(alpha[left],alpha[right],ORDER);need(ec.scalar(t,P)==R,"control input relation");auto q=probe(ec,base,R,false);need(!q.rels.empty(),"control decomposition");for(const auto&rel:q.rels)matrix.add_row(rel,t);setup.push_back({{"index",i},{"rank",matrix.rows.size()},{"relation_count",q.rels.size()},{"actual_groebner_used",true}});}need(matrix.rows.size()==12,"full-rank control failed");Point Q=ec.op(base[5],ec.neg(base[10]));auto q=probe(ec,base,Q,false);need(!q.rels.empty(),"target control decomposition");U k=matrix.recover(q.rels[0]);need(ec.scalar(k,P)==Q&&k==sub(alpha[5],alpha[10],ORDER),"control recovery");save(root+"/validation/ic_full_pipeline_control.json",{{"passed",true},{"label","deliberately planted known-relation positive control; not the random campaign"},{"rank",12},{"setup",setup},{"verified_recovery_equation",true},{"factorbase_logs_imported_into_row_solver",false},{"checker_answers_file_read",false},{"main_random_fixture_recoveries_added",0},{"not_a_performance_or_relation_yield_result",true}});std::cout<<"Planted full-pipeline control passed: actual GB relations -> rank12 -> verified signed-target recovery; excluded from campaign counts\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
